#: The inspector only recognises values of these types. A kernel that has not loaded them holds none of their values.
VALUE_TYPES = ('numpy', 'pandas')

def _key(name): return re.sub(r'[-_.]+', '-', name).lower()

@cache
def inspector_modules(root=INSPECTOR[0], skip=VALUE_TYPES):
    "The top-level modules of `root`'s runtime dependencies, which a kernel may load from the host for `root` alone."
    from importlib.metadata import PackageNotFoundError, packages_distributions, requires
    seen, todo = set(), [root]
    while todo:
        if (k := _key(n := todo.pop())) in seen: continue
        seen.add(k)
        try: todo += [re.match(r'[\w.-]+', r)[0] for r in requires(n) or [] if 'extra ==' not in r]
        except PackageNotFoundError: pass
    return tuple(sorted(m for m, ds in packages_distributions().items()
                        if m != root and m not in skip and any(_key(d) in seen for d in ds)))

