def inspector_loader():
    "Source that loads the host's Dhrishti into a kernel of the host's Python; '' when the host has no Dhrishti."
    spec = importlib.util.find_spec(INSPECTOR[0])
    if spec is None or not spec.origin: return ''
    init = str(Path(spec.origin).resolve())
    return INSPECTOR_LOADER.format(version=HOST_PY, names=inspector_modules(), support=support_paths(),
        dhrishti_init=init, dhrishti_dir=str(Path(init).parent))

