def _probe(python, module, pre=''):
    "Whether `module` imports in `python` after the source `pre` runs, with its version or the failure."
    p = _run([python, '-c', f'{pre}\nimport {module}; print(getattr({module}, "__version__", "installed"))'], 15)
    return {'available': p.returncode == 0,
        'version': p.stdout.strip() if p.returncode == 0 else '',
        'error': _last_line(p.stderr or p.stdout) if p.returncode else ''}

# %% ../nbs/01_support.ipynb #2fe74645
def _vt(v):
    "The first two numbers of version string `v`, or None."
    try: return tuple(int(x) for x in str(v).split('.')[:2])
    except ValueError: return None

def _dist_version(python, name):
    "`name`'s version from the dist-info in the venv `python` belongs to, read off the disk; None when that cannot say."
    root = Path(python).parent.parent
    if not (root/'pyvenv.cfg').is_file(): return None
    found = {d.name[len(name)+1:-len('.dist-info')] for site in [*root.glob('lib*/python*/site-packages'), root/'Lib'/'site-packages']
             for d in site.glob(f'{name}-*.dist-info')}
    return found.pop() if len(found) == 1 else None    # two left by a broken install: only the interpreter knows which wins

def ipykernel_version(python=None):
    "The ipykernel version `python` launches, read from its metadata without importing it; '' when it has none."
    exe = str(Path(python).expanduser()) if python else sys.executable
    if os.path.abspath(exe) == os.path.abspath(sys.executable):
        from importlib.metadata import PackageNotFoundError, version
        try: return version('ipykernel')
        except PackageNotFoundError: return ''
    if (v := _dist_version(exe, 'ipykernel')): return v
    p = _run([exe, '-c', 'import importlib.metadata as m; print(m.version("ipykernel"))'], 15)
    return p.stdout.strip() if p.returncode == 0 else ''

def ipykernel_notice(python=None, version=None):
    "What a host shows for an ipykernel whose shell can stop answering, or None. `version` skips the read."
    v = ipykernel_version(python) if version is None else version
    if not (t := _vt(v)) or not (7, 0) <= t < IPYKERNEL_FLOOR: return None
    floor = '.'.join(map(str, IPYKERNEL_FLOOR))
    return {'kind': 'ipykernel_stall', 'python': str(python or ''), 'version': v, 'floor': floor,
        'message': f'This environment has ipykernel {t[0]}.{t[1]}, which can stop answering. Upgrade it to {floor} or later.'}

# %% ../nbs/01_support.ipynb #b2ac2073
def kernel_support(python):
    "Importability of both supported kernel launchers in ``python``; the ipykernel entry carries `ipykernel_notice`."
    python = str(Path(python).expanduser())
    s = {m: _probe(python, m) for m in ('ipykernel', 'ipymini')}
    s['ipykernel']['notice'] = ipykernel_notice(python, s['ipykernel']['version']) if s['ipykernel']['available'] else None
    return s

# %% ../nbs/01_support.ipynb #96fb5abf
def inspector_support(python, refresh=False):
    "Check whether `python` can import the live-variable inspector, returning what blocked it if not."
    python = str(Path(python).expanduser())
    hit = _INSPECT.get(python)
    if not refresh and hit and time.time() - hit[0] < INSPECTOR_TTL: return hit[1]
    state = _probe(python, 'dhrishti.serving', inspector_loader())
    _INSPECT[python] = (time.time(), state)
    return state

IMPORT_FAULTS = ('ModuleNotFoundError', 'ImportError', 'No module named')

def import_failure(err):
    "Whether bootstrap failed on an inspector import."
    return any(s in (err or '') for s in IMPORT_FAULTS)

# %% ../nbs/01_support.ipynb #fdd325b4
def installable(python):
    "Whether anything may install into `python`. Never this one, and never inside a signed bundle."
    if not python: return False
    p = os.path.abspath(str(python))
    if p == os.path.abspath(sys.executable): return False
    return '/Contents/Resources/' not in p and '/Contents/MacOS/' not in p

# %% ../nbs/01_support.ipynb #a9657e48
def as_installed(names=KERNEL_PACKAGES):
    "Pin `names` to the versions this process runs; leave unpinned what it doesn't have, so installs stay compatible with the host."
    from importlib.metadata import PackageNotFoundError, version
    out = []
    for name in names:
        try: out.append(f'{name}=={version(name)}')
        except (PackageNotFoundError, ValueError, OSError): out.append(name)
    return out

# %% ../nbs/01_support.ipynb #63c63f31
def kernel_requirements(names=KERNEL_PACKAGES):
    "What an install asks for: ipykernel at `IPYKERNEL_FLOOR` or later, the rest pinned by `as_installed`."
    names = list(names)
    floor = 'ipykernel>=' + '.'.join(map(str, IPYKERNEL_FLOOR))
    return [floor if n == 'ipykernel' else r for n, r in zip(names, as_installed(names))]

# %% ../nbs/01_support.ipynb #45ff1680
def _attempts(python, packages):
    "Installer commands to try, in order, for environments that intentionally lack pip."
    out = []
    if uv := shutil.which('uv'): out.append([uv, 'pip', 'install', '--python', python, *packages])
    out.append([python, '-m', 'pip', 'install', *packages])
    if not uv and _run([python, '-m', 'ensurepip', '--upgrade']).returncode == 0:
        out.insert(0, [python, '-m', 'pip', 'install', *packages])
    return out

# %% ../nbs/01_support.ipynb #2dd32fe7
def _log(command, p): return {'command': command, 'returncode': p.returncode,'output': (p.stdout + '\n' + p.stderr).strip()[-8000:]}
def _detail(logs): return next((a['output'] for a in reversed(logs) if a['output']), 'no installer answered')

# %% ../nbs/01_support.ipynb #c4af38c4
def _python_version(python):
    "`(major, minor)` of `python`, or None when it does not answer."
    p = _run([python, '-c', 'import sys; print(*sys.version_info[:2])'], 15)
    try: return tuple(map(int, p.stdout.split()))[:2] if p.returncode == 0 else None
    except ValueError: return None

def install_kernel_support(python, packages=None):
    "Install kernel packages via uv or pip; verify the import works after, so failures name the package not the installer."
    python = str(Path(python).expanduser().absolute())
    if (v := _python_version(python)) and v < MIN_PY: raise RuntimeError(
        f'{python} is Python {v[0]}.{v[1]}, and kernel support needs Python {MIN_PY[0]}.{MIN_PY[1]} or later. '
        'Choose another interpreter, or make the environment again with a newer Python.')
    packages, logs, unimportable = list(packages or kernel_requirements()), [], ''
    with _lock_for(python):
        for command in _attempts(python, packages):
            p = _run(command, 600)
            logs.append(_log(command, p))
            if p.returncode == 0:
                support = kernel_support(python)
                if all(x['available'] for x in support.values()): return {'ok': True, 'python': python, 'support': support, 'attempts': logs}
                unimportable = '; '.join(f"{name} installed but does not import ({x['error']})" for name, x in support.items() if not x['available'])
    raise RuntimeError(f'kernel support installation failed: {unimportable or _detail(logs)}')

# %% ../nbs/01_support.ipynb #e5e916b1
def make_venv(root, python=None):
    "Make `root/.venv` on `python` (this Python's minor by default) with kernel support; its interpreter. An existing venv is kept; a half-made one is removed."
    root = Path(root)
    target = root/'.venv'
    with _lock_for(target):
        if (py := nearest_python(root, root)): return py
        if target.exists(): raise FileExistsError(f'{target} exists and holds no interpreter; remove it or choose an interpreter')
        try:
            if uv := shutil.which('uv'):
                p = _run([uv, 'venv', target, '--python', python or '%d.%d' % HOST_PY], 600)
                if p.returncode: raise RuntimeError(f'uv venv failed: {_last_line(p.stderr or p.stdout)}')
            else:
                import venv
                venv.EnvBuilder(with_pip=True).create(target)
            install_kernel_support(py := target/VENV_BINS[os.name == 'nt'])
            return str(py)
        except BaseException:
            shutil.rmtree(target, ignore_errors=True)
            raise

# %% ../nbs/01_support.ipynb #4ce3e0ba
def install_inspector_support(python, packages=INSPECTOR):
    "Give `python` its own copy of what the inspector imports, then ask it again."
    python = str(Path(python).expanduser().absolute())
    logs = []
    with _lock_for(python):
        for command in _attempts(python, packages):
            p = _run(command, 600)
            logs.append(_log(command, p))
            if p.returncode != 0: continue
            state = inspector_support(python, refresh=True)
            if state['available']: return {'ok': True, 'python': python, 'inspector': state, 'attempts': logs}
            raise RuntimeError(f'{" and ".join(packages)} are installed, and the inspector still will not import: {state["error"]}')
    raise RuntimeError(f'could not install {" and ".join(packages)}: {_detail(logs)}')
